func TestRun_DefaultTimeout(t *testing.T) {
	t.Parallel()

	if _, err := exec.LookPath("sh"); err != nil {
		t.Skip("sh not available")
	}

	// Script that sleeps longer than the default timeout.
	script := `#!/bin/sh
case "$1" in
  info)
    echo '` + validInfoJSON + `'
    ;;
  slow)
    sleep 60
    ;;
esac
`
	binPath := testBinaryDir(t, script)
	ea, err := New(binPath)
	if err != nil {
		t.Fatalf("New: %v", err)
	}

	// With context.Background() (no deadline), run() should apply the default
	// timeout and kill the process instead of blocking for 60s.
